 b=[x for x in a if x.get('experiment')==e]; c=[x for x in b if (x.get('platform') or {}).get('quality')==100];
 if len(b)<2: continue
 def med(f):return round(st.median(f(x) for x in b if f(x) is not None),3)
 print(e,len(b),len(c),'med cost',med(lambda x:x['platform'].get('cost_usd')),'med dur',med(lambda x:x['platform'].get('scored_duration_s')),'med req',med(lambda x:x.get('requests')))
